    [9527]={name="Spellshifter Rod",quality=2,ilvl=46,sourceType="quest_reward",instructions="Reward from the quest 'Tiara of the Deep'. In Zul'Farrak.",zone="Zul'Farrak",questName="Tiara of the Deep",lore="Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep. And not only was it pretty--it held great power for those with the knowledge to use it."},
    [9536]={name="Fairywing Mantle",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'A Fine Mess' - pick it over the other choices. In Gnomeregan.",zone="Gnomeregan",questName="A Fine Mess",lore="Wha.. What happened? The last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs."},
    [9605]={name="Repairman's Cape",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Data Rescue'. In Gnomeregan.",zone="Gnomeregan",questName="Data Rescue",lore="When we fled Gnomeregan, we left so much data behind! Vitally important data! I need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan."},
    [9635]={name="Master Apothecary Cape",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Return to Apothecary Zinge' - pick it over the other choices. In Undercity.",zone="Undercity",questName="Return to Apothecary Zinge",lore="You secure the sealed testing kit for the journey back to the Undercity. Apothecary Zinge waits for you and the sealed field testing kit there."},
    [9648]={name="Chainlink Towel",quality=2,ilvl=48,sourceType="quest_reward",instructions="Reward from the quest 'Rescue OOX-22/FE!' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Rescue OOX-22/FE!",lore="The gnome's voice crackles once again from the robot: \"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure."},
    [9649]={name="Royal Highmark Vestments",quality=3,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Venom to the Undercity' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Venom to the Undercity",lore="The venom you gathered from the Witherbark's spider god is quite a find! I've been able to kill nearly two dozen rabbits with just a drop of the stuff."},
