    [11855]={name="Tork Wrench",quality=2,ilvl=19,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange Manual' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange Manual",lore="I think I can fix the samophlange, but I'm going to need the user's manual first."},
    [11859]={name="Jademoon Orb",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'A Grim Discovery' - pick it over the other choices. In Feralas.",zone="Feralas",questName="A Grim Discovery",lore="What?! Ah, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it? You did the work, so I suppose it is only right you reap the greatest reward from it."},
    [11868]={name="Choking Band",quality=2,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Ogre Head On A Stick = Party' - pick it over the other choices. In Burning Steppes.",zone="Burning Steppes",questName="Ogre Head On A Stick = Party",lore="Just one last thing you must do, soldier. I've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground."},
    [11873]={name="Ethereal Mist Cape",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'Ancient Spirit' - pick it over the other choices. In Felwood.",zone="Felwood",questName="Ancient Spirit",lore="Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos... The skull of Gul'dan ensured that none were spared here."},
    [11904]={name="Spirit of Aquementas",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'It's Dangerous to Go Alone' - pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="It's Dangerous to Go Alone",lore="I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero..."},
    [11908]={name="Archaeologist's Quarry Boots",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Roll the Bones' - pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="Roll the Bones",lore="You'd think that being chief digger for Marshal Expeditions means I like digging. There might be worse things to do in this world... but none really leap to mind."},
    [11934]={name="Emperor's Seal",quality=3,ilvl=61,reqLevel=55,sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan in Blackrock Depths.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Emperor of the Dark Iron, whose ancestor's summoning of Ragnaros doomed the clan. He took Moira Bronzebeard prisoner and she chose to stay."},
    [11936]={name="Relic Hunter Belt",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'The Absent Minded Prospector' - pick it over the other choices. In Darkshore.",zone="Darkshore",questName="The Absent Minded Prospector",lore="So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him."},
