    [21186]={name="Rockfury Bracers",quality=4,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Stalwart's Battlegear' - pick it over the other choices. In Silithus.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
    [21273]={name="Blessed Qiraji Acolyte Staff",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Regalia' - pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Imperial Qiraji Regalia",lore="I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power."},
    [21275]={name="Blessed Qiraji Augur Staff",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Regalia' - pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Imperial Qiraji Regalia",lore="I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power."},
    [21311]={name="Earth Warder's Vest",quality=2,ilvl=48,sourceType="quest_reward",instructions="Reward from the quest 'Timbermaw Ally' - pick it over the other choices. In Felwood.",zone="Felwood",questName="Timbermaw Ally",lore="The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe."},
    [21318]={name="Earth Warder's Gloves",quality=2,ilvl=58,sourceType="quest_reward",instructions="Reward from the quest 'Winterfall Activity' - pick it over the other choices. In Timbermaw Hold.",zone="Timbermaw Hold",questName="Winterfall Activity",lore="The Timbermaw tend to stay to themselves. While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible."},
    [21348]={name="Tiara of the Oracle",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Tiara of the Oracle'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Tiara of the Oracle",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21349]={name="Footwraps of the Oracle",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Footwraps of the Oracle'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Footwraps of the Oracle",lore="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."},
    [21350]={name="Mantle of the Oracle",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Mantle of the Oracle'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Mantle of the Oracle",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
    [21351]={name="Vestments of the Oracle",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Vestments of the Oracle'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Vestments of the Oracle",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21352]={name="Trousers of the Oracle",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Trousers of the Oracle'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Trousers of the Oracle",lore="You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power."},
    [21452]={name="Staff of the Ruins",quality=4,ilvl=72,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ossirian the Unscarred in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Ossirian the Unscarred",lore="A qiraji lieutenant holding the Ruins, whose name stopped being accurate the first time a raid used the crystals against him."},
    [21507]={name="Amulet of the Shifting Sands",quality=4,ilvl=70,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Fall of Ossirian' - pick it over the other choices. In Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",questName="The Fall of Ossirian",lore="A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory."},
    [21565]={name="Rune of Perfection",quality=3,ilvl=45,reqLevel=40,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
    [21566]={name="Rune of Perfection",quality=3,ilvl=25,reqLevel=20,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
