    [21583]={name="Cloak of Clarity",quality=4,ilvl=88,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
