    [22937]={name="Gem of Nerubis",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Anub'Rekhan in Naxxramas.",zone="Naxxramas",npc="Anub'Rekhan",lore="A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."},
